INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_DAVIS_EARLY_COPTIC_PAPACY','secondary scholarship','Stephen J. Davis, The Early Coptic Papacy: The Egyptian Church and Its Leadership in Late Antiquity (American University in Cairo Press, 2004)','Standard scholarly history of the Alexandrian patriarchate and the formation of the Coptic (miaphysite) Church from its origins through late antiquity; covers the papal succession, the monastic movement (Anthony, Pachomius, the Kellia/Scetis fathers, Shenoute and the White Monastery), the post-Chalcedonian schism, the major Coptic martyrs of the Diocletianic persecution, and the leadership culture that shaped figures down to the modern Coptic papacy.')
INSERT INTO _e VALUES
 ('ENT_COP_FATHERS','Coptic Fathers and Saints','Collective','Collective hub','Coptic Christian','monasticism, martyrdom, ecclesiastical leadership','B','Hub collective for the venerated abbots, patriarchs, and martyrs of the Egyptian (Coptic) Church; a grouping node, not a cultic figure.'),
 ('ENT_COP_SHENOUTE','Shenoute the Great','Saint','Abbot / Church Father','Coptic Christian','monasticism, Coptic literature, abbacy','B','Archimandrite of the White Monastery near Sohag (d. c.465); the towering author of classical Sahidic Coptic literature, attested by his vast surviving corpus of sermons and letters and by Besa''s Life of Shenoute. Venerated human, not deified.'),
 ('ENT_COP_BESA','Besa of Atripe','Saint','Abbot / disciple','Coptic Christian','monasticism, hagiography','C','Disciple and successor of Shenoute as head of the White Monastery; author of the Life of Shenoute and of monastic letters, attested by that surviving corpus.'),
 ('ENT_COP_PACHOMIUS','Pachomius the Great','Saint','Abbot / founder','Coptic Christian','cenobitic monasticism','B','Founder of cenobitic (communal) monasticism at Tabennesi (d. 348); attested by the Coptic and Greek Lives of Pachomius and his surviving Rule. Verified absent from DB. Venerated human.'),
 ('ENT_COP_MACARIUS','Macarius of Egypt','Saint','Abbot / desert father','Coptic Christian','desert monasticism','B','Founder of the monastic settlement of Scetis (Wadi al-Natrun) in the Nitrian desert (d. c.391); attested in the Apophthegmata Patrum and the Lausiac History. Distinct from Macaria (ENT_MACARIA, a Greek goddess - homonym verified in DB) and Macarius of Alexandria. Verified absent from DB. Venerated human.'),
 ('ENT_COP_MOSES_BLACK','Moses the Black','Saint','Monk / martyr','Coptic Christian','desert monasticism, conversion, martyrdom','C','Former brigand turned ascetic of Scetis under Macarius (d. c.405), martyred by raiding Berbers; attested in the Apophthegmata Patrum. Venerated human.'),
 ('ENT_COP_SAMUEL_CONFESSOR','Samuel the Confessor','Saint','Abbot / confessor','Coptic Christian','monasticism, confession of faith under persecution','C','Seventh-century Coptic abbot of the Monastery of al-Qalamun (the Monastery of St Samuel) in the Fayyum, confessor under Chalcedonian and early Muslim-era pressure; attested by his Coptic Life. Distinct from the prophet Samuel (ENT_ISR_SAMUEL, verified in DB) - homonym noted. Venerated human.'),
 ('ENT_COP_KYRILLOS_VI','Pope Kyrillos VI','Saint','Patriarch / pope','Coptic Christian','Coptic papacy, monastic revival','C','116th Pope of Alexandria (reigned 1959-1971), monastic-revival reformer, canonized by the Coptic Orthodox Church in 2013; placed in the modern period (re-pointed from the proposed late-antique Coptic period, which ends c.1000, to PER_MODERN_ORTHODOX). A 20th-century figure standing in the continuous Alexandrian papal tradition. Venerated human, not deified.'),
 ('ENT_COP_MENA_MARTYR','Mena the Wonderworker (Abu Mina)','Saint','Martyr / wonderworker','Coptic Christian','martyrdom, healing cult, pilgrimage','C','Egyptian (Coptic) reception of the soldier-martyr Menas, centre of the great healing-pilgrimage shrine of Abu Mina west of Alexandria. Cross-links to the existing pan-Orthodox Menas (ENT_ORTH_MENAS, verified in DB) as the same figure venerated in the Coptic tradition; flagged as a homonym/overlap in review.');
