INSERT INTO _r VALUES
 ('ENT_COP_SHENOUTE','member_of','ENT_COP_FATHERS','high','Shenoute is a venerated Coptic abbot-saint, a member of the Coptic Fathers hub (Davis).'),
 ('ENT_COP_BESA','member_of','ENT_COP_FATHERS','high','Besa, Shenoute''s successor at the White Monastery, is a venerated Coptic father.'),
 ('ENT_COP_PACHOMIUS','member_of','ENT_COP_FATHERS','high','Pachomius, founder of cenobitic monasticism in Egypt, is a foundational Coptic father.'),
 ('ENT_COP_MACARIUS','member_of','ENT_COP_FATHERS','high','Macarius of Egypt, founder of Scetis, is a foundational Coptic desert father.'),
 ('ENT_COP_MOSES_BLACK','member_of','ENT_COP_FATHERS','high','Moses the Black, monk-martyr of Scetis, is a venerated Coptic father.'),
 ('ENT_COP_SAMUEL_CONFESSOR','member_of','ENT_COP_FATHERS','high','Samuel the Confessor, abbot of al-Qalamun, is a venerated Coptic father.'),
 ('ENT_COP_KYRILLOS_VI','member_of','ENT_COP_FATHERS','high','Pope Kyrillos VI, canonized Coptic patriarch, belongs to the Coptic Fathers and Saints hub.'),
 ('ENT_COP_MENA_MARTYR','member_of','ENT_COP_FATHERS','high','Mena/Abu Mina, the great Coptic healing-martyr, is a venerated Coptic saint.'),
 ('ENT_COP_BESA','taught_by','ENT_COP_SHENOUTE','high','Besa was the disciple of Shenoute and succeeded him as archimandrite of the White Monastery (Davis; Besa''s own Life of Shenoute).'),
 ('ENT_COP_MOSES_BLACK','taught_by','ENT_COP_MACARIUS','medium','Moses the Black became a monk of Scetis under the spiritual direction of Macarius of Egypt (Apophthegmata Patrum).'),
 ('ENT_SAINT_ANTHONY_ABBOT','member_of','ENT_COP_FATHERS','high','Anthony the Great (existing ENT_SAINT_ANTHONY_ABBOT, verified in DB), the Egyptian father of monasticism, is venerated as the foremost Coptic father; wiring the existing entity into the Coptic hub.'),
 ('ENT_COP_PACHOMIUS','reception_of','ENT_SAINT_ANTHONY_ABBOT','medium','Pachomian cenobitism develops the Egyptian eremitic ideal pioneered by Anthony the Great, the model anchorite (Davis); object verified to exist in DB.'),
 ('ENT_COP_MACARIUS','reception_of','ENT_SAINT_ANTHONY_ABBOT','medium','Macarius of Egypt is portrayed in the Apophthegmata as carrying forward the desert ascetic tradition founded by Anthony the Great; object verified to exist in DB.'),
 ('ENT_ORTH_ATHANASIUS','member_of','ENT_COP_FATHERS','high','Athanasius of Alexandria (existing ENT_ORTH_ATHANASIUS, verified in DB), the Coptic patriarch and biographer of Anthony, is a foundational Coptic father; wiring the existing entity into the Coptic hub.'),
 ('ENT_COP_KYRILLOS_VI','reception_of','ENT_ORTH_ATHANASIUS','medium','As a successor Pope of Alexandria, Kyrillos VI stands in the continuous Alexandrian patriarchal line whose great early model is Athanasius (Davis, on the papal succession); object verified to exist in DB.'),
 ('ENT_COP_MENA_MARTYR','received_as','ENT_ORTH_MENAS','high','The Coptic wonderworker Mena (Abu Mina) is the Egyptian/Coptic reception of the same soldier-martyr venerated pan-Orthodox as Menas (existing ENT_ORTH_MENAS, verified in DB); same figure, flagged as a homonym/overlap.');
